import{z as o,x as n,o as B,c as D,q as r,j as i,D as a,d as e,s as t,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"失败归因的次序","description":"","frontmatter":{"title":"失败归因的次序","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-failure-attribution.md","filePath":"llm/rw-failure-attribution.md","lastUpdated":1791413859000}'),d={name:"llm/rw-failure-attribution.md"};function p(m,E,f,h,C,S){const l=n("Mermaid");return B(),D("div",null,[E[2]||(E[2]=r('<h1 id="失败归因的次序" tabindex="-1">失败归因的次序 <a class="header-anchor" href="#失败归因的次序" aria-label="Permalink to &quot;失败归因的次序&quot;">​</a></h1><div class="epigraph"><p>神经网络的失败大多是沉默的：代码照常运行，只是训练坏了；所以排查必须靠纪律，不靠报错。</p><footer>—— 据 Karpathy, A Recipe for Training Neural Networks, 2019 整理</footer></div><p><a href="/llm/rw-ablation-design">上一课</a>的消融在部件之间做受控比较；本课处理它的逆问题：复现对不上时，差异到底藏在哪一层。嫌疑空间是一个乘积——数据、分词、初始化、优化器、日程、数值、评测协议，七层任何一层都足以毁掉全部数字。乱枪排查的代价不只是算力：试到第十几枪时，你已经在噪声里「看到」过各种假信号，归因从此失去证据资格。缺的是一个固定的排查次序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>归因的困难有两个来源。第一，层的乘积太大：全组合排查是指数的，必须逐步缩小空间。第二，观测不区分层：一条异常 loss 曲线可以是数据坏了，也可以是学习率坏了，也可以是评测脚本坏了——症状相同，病灶不同。所以次序必须按两个原则排：从外向内（先检查离训练最远的层，评测与数据，再进入训练本体），从便宜到贵（分钟级检查排前，天级复算排后）。每个原则单独用都会失败：只按便宜排会先调学习率，只由内向外会烧掉预算才发现问题出在评测脚本。</p><p><span class="marginnote">为什么说嫌疑空间是「乘积」：七层里每层哪怕只有 3 个嫌疑点，组合也有 3 的 7 次方约 2187 种——逐个试不可能。固定次序的意义就是每层砍掉一个维度，把指数空间拆成一串线性检查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六步次序，每步只验证一个假设，验证失败（该层对齐了仍不对）才进下一步。第一步评测协议对齐：换用对方的评分脚本与提示模板重测自己的输出——最便宜的检查，也截获最多假失败。第二步数据指纹对齐：快照版本、清洗规则、去重阈值、配比，逐项比。第三步配置 diff：把你的配置与参考配置逐项并列，差异清单里没有解释的项逐个消去。第四步 loss 初值检查：小批数据上的初始 loss 应约等于词表上的均匀分布熵；差一位数就是归一化、词表映射或 padding 出错。第五步优化动态：学习率爬坡曲线、梯度范数序列，对照<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>的形态学——上不去查数据与学习率，震荡查数值，后段发散查日程。第六步才全量复算。层与层之间的换件法是二分：把对方的数据喂进你的管线，或反之，一次实验对半切开嫌疑空间。</p><p><span class="marginnote">数字实例：few-shot 示例从 5 个换成 3 个、或提示模板尾部多个空格，某些基准能差出一两个点——比多数「方法改进」还大。所以第一步才放评测协议：几分钟的检查，排掉的假失败最多。</span></p>',9)),(B(),i(s,null,{default:a(()=>[t(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E5%A4%8D%E7%8E%B0%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%5D%20--%3E%20S1%5B%221%20%E8%AF%84%E6%B5%8B%E5%8D%8F%E8%AE%AE%E5%AF%B9%E9%BD%90%22%5D%0A%20%20S1%20--%3E%20S2%5B%222%20%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%E5%AF%B9%E9%BD%90%22%5D%0A%20%20S2%20--%3E%20S3%5B%223%20%E9%85%8D%E7%BD%AE%E9%80%90%E9%A1%B9%20diff%22%5D%0A%20%20S3%20--%3E%20S4%5B%224%20loss%20%E5%88%9D%E5%80%BC%20vs%20%E5%9D%87%E5%8C%80%E7%86%B5%22%5D%0A%20%20S4%20--%3E%20S5%5B%225%20%E4%BC%98%E5%8C%96%E5%8A%A8%E6%80%81%E5%BD%A2%E6%80%81%22%5D%0A%20%20S5%20--%3E%20S6%5B%226%20%E5%85%A8%E9%87%8F%E5%A4%8D%E7%AE%97%22%5D%0A%20%20S1%20--%3E%7C%22%E5%B7%B2%E5%AF%B9%E9%BD%90%E4%BB%8D%E4%B8%8D%E5%AF%B9%22%7C%20S2%0A%20%20S2%20--%3E%7C%22%E5%B7%B2%E5%AF%B9%E9%BD%90%E4%BB%8D%E4%B8%8D%E5%AF%B9%22%7C%20S3%0A%20%20S3%20--%3E%7C%22%E6%97%A0%E6%B3%95%E8%A7%A3%E9%87%8A%22%7C%20S4%0A%20%20S4%20--%3E%7C%22%E6%AD%A3%E5%B8%B8%22%7C%20S5%0A%20%20S5%20--%3E%7C%22%E5%AE%9A%E4%BD%8D%22%7C%20ARCH%5B%22%E6%AD%BB%E5%9B%A0%E8%90%BD%E5%88%A4%E6%8D%AE%EF%BC%8C%E5%BD%92%E6%A1%A3%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"为什么 loss 初值是枢纽锚点：它把优化动力学冻结掉，只剩前向计算与数据管道——第一性检查里信息量最大的单点。语言模型的心算口径：词表 3.2 万，均匀分布熵约为 \\(\\ln(32000) \\approx 10.4\\)，第一步 loss 落在 10 到 11 属正常；一上来就是两位数，基本不用看训练，问题在映射或归一化。为什么评测协议排最前：它决定「对不上」这个症状本身是否成立——模板差一个空格、few-shot 数不同，都能造出几个点的假差距，后面的层根本无病。",-1)),(B(),i(s,null,{default:a(()=>[t(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%A4%8D%E7%8E%B0%E5%AF%B9%E4%B8%8D%E4%B8%8A%EF%BC%9A%E6%95%B0%E6%8D%AE%E4%B8%8E%E7%AE%A1%E7%BA%BF%E8%B0%81%E6%98%AF%E5%87%B6%E6%89%8B%22%5D%20--%3E%20SW%5B%22%E6%8D%A2%E4%BB%B6%E5%AE%9E%E9%AA%8C%EF%BC%9A%E5%AF%B9%E6%96%B9%E6%95%B0%E6%8D%AE%E5%96%82%E8%BF%9B%E4%BD%A0%E7%9A%84%E7%AE%A1%E7%BA%BF%22%5D%0A%20%20SW%20--%3E%20A%5B%22%E6%95%B0%E5%AD%97%E7%AB%8B%E5%88%BB%E5%AF%B9%E4%B8%8A%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%87%B6%E6%89%8B%E5%9C%A8%E4%BD%A0%E6%96%B9%E6%95%B0%E6%8D%AE%EF%BC%9A%E5%9B%9E%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%E5%B1%82%22%5D%0A%20%20SW%20--%3E%20B%5B%22%E6%95%B0%E5%AD%97%E4%BB%8D%E7%84%B6%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%87%B6%E6%89%8B%E5%9C%A8%E4%BD%A0%E6%96%B9%E7%AE%A1%E7%BA%BF%EF%BC%9A%E5%9B%9E%E9%85%8D%E7%BD%AE%E4%B8%8E%E5%8A%A8%E6%80%81%E5%B1%82%22%5D%0A%20%20A1%20--%3E%20H%5B%22%E5%AB%8C%E7%96%91%E7%A9%BA%E9%97%B4%E5%87%8F%E5%8D%8A%EF%BC%8C%E9%80%90%E5%B1%82%E6%94%B6%E7%AA%84%22%5D%0A%20%20B1%20--%3E%20H%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：看到第一步 loss 冲到 20 就去调学习率。初值异常与优化器无关——模型还没开始学，学习率还没起作用。两位数初值指向的是词表映射、归一化或 padding 这类「前向管道」问题，先修管道再谈训练。</span></p><p>归因的终点纪律：找到「足以支撑目标线的差异」就停。复现不追求唯一真因——有些差异作者自己也解释不了（历史上有效的神秘超参），归因到「披露不足」一级就够进报告。每个死因必须落在判据上：「效果不好」不是数据，「换用对方评分脚本后差距从 2.1 缩到 0.2」才是数据。</p><p><span class="marginnote">失败实验要归档而不是删除：死路是团队资产，<a href="/llm/ti-failed-exp-archive">失败实验的归档</a>要求失败与成功同模板入库、死因落判据。归因台账的价值在半年后——下一个复现同一论文的人，你的排除记录是他跳过的全部算力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>归因次序不是教条：第四步的初值检查便宜到近乎免费，可以随第一步一起做；但对数据的怀疑必须按次序升降——数据指纹对齐过一次后，短期内降级为低嫌疑，除非换了快照。不把归因当追责：记录以差异为中心，不以人为中心，否则团队会学会隐瞒失败。也无法归因到零：预算耗尽时，剩余嫌疑写成「未排除项」进入报告的置信度档位，而不是含混地写「基本复现」。有些复现差异最终落在不可归因区（作者环境不可复原），这不是失败，是方法复现这门手艺的常规成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排查次序两原则：从外向内、从便宜到贵；六步是评测、数据、配置、初值、动态、全量。</li><li>每步只验证一个假设，验证不过关才进下一层；换件法实现二分。</li><li>loss 初值对均匀熵是最便宜的高信息锚点；语言模型口径约 \\(\\ln V\\)。</li><li>死因必须落在判据上，失败实验同模板归档，负结果可检索。</li><li>归因到「足以支撑目标线」即止；剩余嫌疑写成未排除项降档进报告。</li><li>出处：Karpathy, 2019；曲线形态学见<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>；归档纪律见<a href="/llm/ti-failed-exp-archive">失败实验的归档</a>。</li></ul>',7))])}const F=o(d,[["render",p]]);export{c as __pageData,F as default};
